// Cadrage figé du besoin : la découverte est pilotée par la question de veille, jamais par la source.
// Les critères d'admissibilité reprennent la qualification du ch. 8 (fréquence, format, accès).
return [{ json: {
  secteur: 'automobile',
  question_veille: 'QV5',
  intitule_besoin: "Impulsions et soutiens publics à l'électrification de la filière automobile",
  perimetre_geo: 'UE, Chine, États-Unis',
  profondeur_historique_ans: 3,
  criteres_admissibilite: [
    'Producteur institutionnel, statistique officiel, organisation internationale ou association de branche reconnue',
    'Accès gratuit et sans authentification',
    'Publication périodique et datée (mensuelle à annuelle)',
    'Format exploitable : API, CSV/Excel, ou document structuré récurrent',
    'Série disponible sur au moins trois exercices'
  ],
  prompt: "Tu assistes la constitution d'un référentiel de sources pour une veille économique sectorielle. Propose au maximum 8 sources répondant au besoin décrit, en respectant STRICTEMENT les critères d'admissibilité fournis. Règles impératives : (1) ne propose que des sources dont tu es certain qu'elles existent ; (2) ne propose aucune URL que tu ne peux pas justifier ; (3) si tu n'as pas de proposition fiable, renvoie une liste vide plutôt qu'une proposition incertaine ; (4) réponds UNIQUEMENT par un JSON strict, sans texte autour, au format {\"sources\":[{\"nom\":\"\",\"organisme\":\"\",\"url\":\"\",\"indicateur_couvert\":\"\",\"frequence\":\"\",\"format\":\"\",\"acces\":\"gratuit|inscription|payant\",\"profondeur_historique\":\"\",\"justification\":\"\"}]}."
} }];

// Fusion des propositions, normalisation des URL et calcul du recouvrement inter-modèles.
// Le recouvrement est un signal de priorisation, jamais une preuve : la vérification objective suit (§ 6.3).
//
// Extraction portée le 22.08.2026 sur les formes de réponse réellement observées à la
// vague 3 (annexe_3/vague3/*.brut.json). Trois formes ont changé avec l'activation de la
// recherche web : le premier bloc de contenu n'est plus le texte, ce sont les blocs
// d'appel d'outil. Il faut concaténer TOUS les blocs de texte, et non lire l'indice 0.
function texte(x) {
  // OpenAI, API Responses : output[] contient des web_search_call puis un message.
  if (Array.isArray(x.output)) {
    return x.output.filter(o => o.type === 'message')
      .flatMap(o => (o.content || []).filter(c => c.type === 'output_text').map(c => c.text))
      .join('\n');
  }
  // Anthropic : content[] mêle server_tool_use, web_search_tool_result et text.
  if (Array.isArray(x.content)) {
    return x.content.filter(b => b.type === 'text').map(b => b.text).join('\n');
  }
  // Google : candidates[0].content.parts[] peut compter plusieurs parts textuelles.
  if (Array.isArray(x.candidates)) {
    return (x.candidates[0]?.content?.parts || []).filter(p => p.text).map(p => p.text).join('\n');
  }
  // Perplexity : /v1/sonar conserve la forme chat completions (vérifié sur archive d'essai).
  return x.choices?.[0]?.message?.content ?? '';
}
// Attribution par forme de réponse plutôt que par rang d'arrivée : le rang dépend de la
// latence de chaque fournisseur, l'attribution ne doit pas en dépendre.
function modeleDe(x, i) {
  if (Array.isArray(x.output)) return 'openai';
  if (Array.isArray(x.content)) return 'anthropic';
  if (Array.isArray(x.candidates)) return 'google';
  if (x.choices) return 'perplexity';
  return 'modele_' + i;
}
const MODELES = ['openai', 'anthropic', 'google', 'perplexity'];

function parser(t) {
  try { return (JSON.parse(String(t).replace(/^```json/i, '').replace(/^```/, '').replace(/```$/, '').trim()).sources) || []; }
  catch (e) { return []; }
}
function cle(u) {
  try { const p = new URL(u); return (p.hostname.replace(/^www\./, '') + p.pathname.replace(/\/$/, '')).toLowerCase(); }
  catch (e) { return String(u || '').toLowerCase().trim(); }
}

const registre = {};
const modelesVus = [];
$input.all().forEach((item, i) => {
  const modele = modeleDe(item.json, i);
  if (!modelesVus.includes(modele)) modelesVus.push(modele);
  for (const s of parser(texte(item.json))) {
    const k = cle(s.url);
    if (!k) continue;
    if (!registre[k]) registre[k] = { cle: k, url: s.url, nom: s.nom, organisme: s.organisme, propositions: {}, modeles: [] };
    registre[k].propositions[modele] = s;
    if (!registre[k].modeles.includes(modele)) registre[k].modeles.push(modele);
  }
});

const contexte = $('Cadrer le besoin de veille').first().json;
const candidats = Object.values(registre).map(c => ({
  cle: c.cle,
  url: c.url,
  nom: c.nom,
  organisme: c.organisme,
  modeles: c.modeles,
  nb_modeles: c.modeles.length,
  indice_recouvrement: c.modeles.length / MODELES.length,
  propositions: c.propositions,
  secteur: contexte.secteur,
  question_veille: contexte.question_veille,
  intitule_besoin: contexte.intitule_besoin
})).sort((a, b) => b.nb_modeles - a.nb_modeles);

const union = candidats.length;
const noyau = candidats.filter(c => c.nb_modeles >= 3).length;
return [{ json: {
  releve_le: new Date().toISOString(),
  modeles_ayant_repondu: modelesVus,
  union_propositions: union,
  noyau_commun: noyau,
  indice_recouvrement_global: union ? noyau / union : 0,
  candidats
} }];

// Fiche de qualification pré-remplie, alignée sur la table `indicators` du schéma consolidé.
// Les champs de décision restent vides : le workflow prépare la décision, il ne la prend pas.
// Le nœud HTTP précédent ne renvoie que la réponse ; les données du candidat sont reprises par appariement d'items.
const cand = $('Éclater les candidats').item.json;
const referentiel = $('Réduire le référentiel à un item').first().json.referentiel;

function cle(u) {
  try { const p = new URL(u); return (p.hostname.replace(/^www\./, '') + p.pathname.replace(/\/$/, '')).toLowerCase(); }
  catch (e) { return String(u || '').toLowerCase().trim(); }
}
const dejaConnues = new Set(referentiel.map(r => cle(r.source_url)));

if (dejaConnues.has(cand.cle)) {
  return { json: {
    statut_traitement: 'doublon_referentiel',
    motif: 'Source déjà inscrite au référentiel',
    source_url: cand.url,
    nb_modeles: cand.nb_modeles,
    modeles_proposants: cand.modeles,
    http_status: $json.statusCode ?? null,
    constate_le: new Date().toISOString()
  } };
}

const props = Object.values(cand.propositions || {});
const consensuel = (champ) => {
  const vals = props.map(p => String(p?.[champ] ?? '').trim().toLowerCase()).filter(Boolean);
  return vals.length && vals.every(x => x === vals[0]) ? vals[0] : null;
};

return { json: {
  statut_traitement: 'a_qualifier',
  // Identification
  source_name: cand.organisme || cand.nom || null,
  source_url: cand.url,
  sector: cand.secteur,
  watch_question: cand.question_veille,
  besoin: cand.intitule_besoin,
  // Proposé par les modèles, à confirmer par l'humain (null si les modèles divergent)
  frequency_proposee: consensuel('frequence'),
  format_propose: consensuel('format'),
  acces_propose: consensuel('acces'),
  indicateur_couvert_propose: props.map(p => p?.indicateur_couvert).filter(Boolean),
  justifications: props.map(p => p?.justification).filter(Boolean),
  // Preuves accompagnant la fiche
  nb_modeles: cand.nb_modeles,
  modeles_proposants: cand.modeles,
  indice_recouvrement: cand.indice_recouvrement,
  // Les propositions brutes accompagnent la fiche : `source_qualification_queue.propositions`
  // est NOT NULL, et c'est la pièce qui permet à l'humain de juger sur pièces (§ 6.3).
  propositions: cand.propositions,
  url_verifiee: true,
  http_status: $json.statusCode ?? null,
  verifiee_le: new Date().toISOString(),
  // Champs de décision, laissés vides à dessein
  category: null,
  status: null,
  decision: null,
  decide_par: null,
  decide_le: null
} };

// Journal des propositions non vérifiables : mesure directe du taux d'invention par modèle.
// Alimente la tâche d'identification de sources du protocole expérimental (T1, § 9.1.2)
// et le suivi de fiabilité du dispositif en régime d'exploitation.
const cand = $('Éclater les candidats').item.json;
return { json: {
  statut_traitement: 'non_verifiable',
  motif: 'URL inatteignable ou inexistante à la date de vérification',
  source_url: cand.url,
  nom: cand.nom ?? null,
  organisme: cand.organisme ?? null,
  modeles_proposants: cand.modeles ?? [],
  nb_modeles: cand.nb_modeles ?? null,
  indice_recouvrement: cand.indice_recouvrement ?? null,
  http_status: $json.statusCode ?? null,
  constate_le: new Date().toISOString()
} };

// Réduit le référentiel à UN item : les nœuds de modèle qui suivent doivent
// être appelés une fois, pas une fois par ligne du référentiel.
return [{ json: { referentiel: $input.all().map(i => i.json) } }];
